try{$upsert=$pdo->prepare('INSERT INTO report_values(report_student_id,column_id,numeric_value,text_value,date_value,calculated_value,updated_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE numeric_value=VALUES(numeric_value),text_value=VALUES(text_value),date_value=VALUES(date_value),calculated_value=VALUES(calculated_value),updated_by=VALUES(updated_by)');$computed=[];foreach($payload['rows']??[] as $row){$studentId=(int)($row['report_student_id']??0);if(!isset($allowedStudents[$studentId]))throw new InvalidArgumentException('طالب غير تابع للتقرير.');$values=[];foreach(($row['values']??[]) as $key=>$value){$column=$columns[$key]??null;if(!$column||$column['is_calculated'])continue;if($column['type']==='manual_mark'){$number=$value===''?null:filter_var($value,FILTER_VALIDATE_FLOAT);$step=(float)($column['step_value']?:0.25);$offStep=$number!==null&&abs(($number/$step)-round($number/$step))>0.00001;if($number===false||($number!==null&&($number<0||$number>(float)$column['max_mark']||$offStep)))throw new InvalidArgumentException('علامة خارج المجال أو لا تطابق خطوة الإدخال في '.$column['name']);$values[$key]=$number;}elseif($column['type']==='text'){$text=trim((string)$value);if(mb_strlen($text)>2000)throw new InvalidArgumentException('النص أطول من الحد المسموح.');$values[$key]=$text;}elseif($column['type']==='date'){$date=trim((string)$value);if($date!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new InvalidArgumentException('صيغة التاريخ غير صالحة.');$values[$key]=$date;}}$values=$engine->calculate($template['columns'],$values);foreach($columns as $key=>$column){if(in_array($column['type'],['student_number','student_name'],true)||!array_key_exists($key,$values))continue;$value=$values[$key];$numeric=$column['type']==='manual_mark'?$value:null;$calculated=$column['is_calculated']?$value:null;$text=$column['type']==='text'?$value:null;$date=$column['type']==='date'&&$value!==''?$value:null;$upsert->execute([$studentId,$column['id'],$numeric,$text,$date,$calc